import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Claim } from '../claims/claims';
import { useCurrentSheet } from '../session/session';

/** A grade's rate as the store holds it: the percent with two decimals, from a date on (YYYY-MM-DD; null
 *  when it applies from the beginning of time). */
export type Rate = { grade: string; pct: string; from: string | null };

export const ratesQueryKey = (sheetId: string) => ['sheet', sheetId, 'rates'] as const;

export const ratesPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/rates`;

/** The sheet's rates, by grade, then by from-date (a rate with none first). */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesQueryKey(sheet ?? ''),
    queryFn: () => getJson<Rate[]>(ratesPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

/** The percent ("12.50") of a grade's rate in force on a date (YYYY-MM-DD): the one whose from-date is the
 *  latest on or before it, a rate with no from-date applying from the beginning of time — or undefined when
 *  no rate applies then. */
export function rateOn(rates: Rate[] | undefined, grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (!found || (found.from ?? '') <= (r.from ?? '')) found = r;
  }
  return found?.pct;
}

/** A claim's figure: a settled claim's frozen due, else the figure its person's last statement bound it to,
 *  else its live due at its person's grade's rate on its date, at least the sheet's floor ("n/a" when it has none). */
export function figureOf(c: Claim, rates: Rate[] | undefined, grade: string, floor: string | null | undefined): string {
  if (c.due !== null) return c.due;
  if (c.stated) return c.statedDue ?? 'n/a';
  return atLeast(dueOf(c.amount, rateOn(rates, grade, c.date)), floor);
}

/** A due raised to the floor when below it ("n/a" stays n/a; no floor leaves it as it is). */
export function atLeast(due: string, floor: string | null | undefined): string {
  if (due === 'n/a' || floor == null || floor === '') return due;
  return hundredths(due) < hundredths(floor) ? formatCents(hundredths(floor)) : due;
}

/** A two-decimal string ("12.50") in hundredths, exactly. */
const hundredths = (s: string) => BigInt(Math.round(Number(s) * 100));

/**
 * The due on an amount: amount times the percent, divided by 100, rounded half to even
 * to two decimals — "n/a" when there is no percent. Computed in whole hundredths, so it is exact.
 */
export function dueOf(amount: string, pct: string | undefined): string {
  if (pct === undefined) return 'n/a';
  // hundredths of the amount times hundredths of the percent = the due in millionths of a percent;
  // dividing by 10000 gives cents.
  const product = hundredths(amount) * hundredths(pct);
  const negative = product < 0n;
  const magnitude = negative ? -product : product;
  const rest = magnitude % 10000n;
  let cents = magnitude / 10000n;
  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
  return formatCents(negative ? -cents : cents);
}

/** Whole cents as a two-decimal string. */
export function formatCents(cents: bigint): string {
  const negative = cents < 0n;
  const m = negative ? -cents : cents;
  return `${negative ? '-' : ''}${m / 100n}.${(m % 100n).toString().padStart(2, '0')}`;
}

/** Adds up two-decimal amounts, skipping "n/a". */
export function sumDue(dues: string[]): string {
  return formatCents(dues.filter((d) => d !== 'n/a').reduce((n, d) => n + hundredths(d), 0n));
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { useCurrentSheet } from '../session/session';

/** A user name's role on the sheet: clerk or steward. A name with none is a clerk. */
export type Role = { user: string; role: string };

/** The sheet's settings: its clerk limit with two decimals (null when there is none) and its floor with two
 *  decimals (a claim's live due is at least it), and its terms in days (a claim is due by its date plus them). */
export type Settings = { clerkLimit: string | null; floor: string; terms: string };

/** The terms a sheet starts at, in days. */
export const DEFAULT_TERMS = '14';

export const rolesQueryKey = (sheetId: string) => ['sheet', sheetId, 'roles'] as const;
export const rolesPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/roles`;

export const settingsQueryKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;
export const settingsPath = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/settings`;

/** The user names given a role on the sheet, by name. */
export function useRoles() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: rolesQueryKey(sheet ?? ''),
    queryFn: () => getJson<Role[]>(rolesPath(sheet ?? '')),
    enabled: !!sheet,
  });
}

export function useSettings() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: settingsQueryKey(sheet ?? ''),
    queryFn: () => getJson<Settings>(settingsPath(sheet ?? '')),
    enabled: !!sheet,
  });
}
import { useState, type ReactNode } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, postJson, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import type { Person } from '../people/people';
import { figureOf, useRates } from '../rates/rates';
import { periodOn, usePeriods } from '../periods/periods';
import { DEFAULT_TERMS, useSettings } from '../roles/roles';
import { claimsPath, claimsQueryKey, dueByOf, isOverdue, personClaimsPath, useClaims, useEditingClaim, type Claim } from './claims';

// A person's claims, newest first, with the claim form that adds one — or, while one of their
// claims' editor is open, saves its changes.
function ClaimsHeader() {
  return <th>Claims</th>;
}

function PersonClaims({ person }: { person: Person }) {
  const [sheet] = useCurrentSheet();
  const [editing, setEditing] = useEditingClaim();
  const claims = useClaims();
  const rates = useRates();
  const periods = usePeriods();
  const settings = useSettings();
  const today = useSheetToday();
  const terms = settings.data?.terms ?? DEFAULT_TERMS;
  if (!sheet) return null;
  const mine = (claims.data ?? []).filter((c) => c.personId === person.id);
  const claim = editing ? mine.find((c) => String(c.id) === editing) : undefined;
  return (
    <td>
      <ul data-testid="claims">
        {mine.map((c) => (
          <li key={c.id} data-testid={`claim-row-${c.id}`}>
            <span data-testid="claim-number">{c.number ?? ''}</span>{' '}
            <span data-testid="claim-amount">{c.amount}</span>{' '}
            <span data-testid="claim-date">{c.date}</span>{' '}
            <span data-testid="claim-note" style={{ whiteSpace: 'pre' }}>{c.note}</span>{' '}
            <span data-testid="claim-period">{periodOn(periods.data, c.date)?.name ?? ''}</span>{' '}
            <span data-testid="claim-due">{figureOf(c, rates.data, person.grade, settings.data?.floor)}</span>{' '}
            <span data-testid="claim-stated">{c.stated ? 'yes' : 'no'}</span>{' '}
            <span data-testid="claim-opened-by">{c.openedBy ?? ''}</span>{' '}
            <span data-testid="claim-due-by">{dueByOf(c, terms)}</span>{' '}
            <span data-testid="claim-overdue">{isOverdue(c, terms, today) ? 'yes' : 'no'}</span>{' '}
            <ClaimStatusActions key={`${sheet}:${c.id}`} sheet={sheet} claim={c} onEdit={() => setEditing(String(c.id))}>
              {claim?.id === c.id && (
                <button type="button" data-testid="claim-cancel" onClick={() => setEditing(undefined)}>
                  Cancel
                </button>
              )}
            </ClaimStatusActions>
          </li>
        ))}
      </ul>
      {/* Keyed by the claim being edited, so opening an editor fills the form with its values. */}
      <ClaimForm key={`${sheet}:${claim?.id ?? ''}`} sheet={sheet} person={person} claim={claim} />
    </td>
  );
}

const ACTIONS = [
  { action: 'open', label: 'Open' },
  { action: 'settle', label: 'Settle' },
  { action: 'void', label: 'Void' },
] as const;

// A claim's status and the buttons that change it. A change its status does not allow is refused
// by the server and shows the claim's error, as is settling a claim the signed-in user opened, or a clerk settling one whose due is above the clerk limit; the error goes as soon as the next action on the row
// is taken. Only a DRAFT can be edited: the edit button of any other claim shows the claim's error
// instead of opening its editor (an open claim is voided and added anew).
function ClaimStatusActions({ sheet, claim, onEdit, children }: {
  sheet: string; claim: Claim; onEdit: () => void; children: ReactNode;
}) {
  const [user] = useCurrentUser();
  const queryClient = useQueryClient();
  const change = useMutation({
    mutationFn: (action: string) => putJson<Claim>(`${claimsPath(sheet)}/${claim.id}/${action}`, undefined, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) }),
  });
  const submitChange = useSubmitOnce(change);
  const [editRefused, setEditRefused] = useState(false);
  const periods = usePeriods();
  const closed = !!periodOn(periods.data, claim.date)?.closed;
  return (
    <>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {ACTIONS.map(({ action, label }) => (
        <button
          key={action}
          type="button"
          data-testid={`claim-${action}`}
          disabled={change.isPending}
          onClick={() => {
            setEditRefused(false);
            submitChange(action);
          }}
        >
          {label}
        </button>
      ))}{' '}
      <span onClickCapture={() => { change.reset(); setEditRefused(false); }}>
        <button
          type="button"
          data-testid="claim-edit"
          onClick={() => {
            if (claim.status === 'DRAFT') onEdit();
            else setEditRefused(true);
          }}
        >
          Edit
        </button>
        {children}
      </span>
      {(change.isError || editRefused) && (
        <span data-testid="claim-error">
          {editRefused
            ? `Only a draft claim can be edited; void this ${claim.status} claim and add a new one.`
            : closed
            ? 'This claim is dated in a closed period, so its status cannot change.'
            : change.variables === 'settle' && claim.openedBy === user
            ? 'You opened this claim, so someone else must settle it.'
            : change.variables === 'settle' && change.error instanceof HttpError && change.error.status === 403
            ? 'Its due is above the clerk limit, so only a steward can settle it.'
            : `That status change is not allowed for a ${claim.status} claim.`}
        </span>
      )}
    </>
  );
}

function ClaimForm({ sheet, person, claim }: { sheet: string; person: Person; claim?: Claim }) {
  const [user] = useCurrentUser();
  const [, setEditing] = useEditingClaim();
  const today = useSheetToday();
  const [amount, setAmount] = useState(claim?.amount ?? '');
  const [date, setDate] = useState(claim?.date ?? '');
  const [note, setNote] = useState(claim?.note ?? '');
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: (body: { amount: string; date: string; note: string }) =>
      claim
        ? putJson<Claim>(`${claimsPath(sheet)}/${claim.id}`, body, user)
        : postJson<Claim>(personClaimsPath(sheet, person.id), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsQueryKey(sheet) });
      if (claim) {
        setEditing(undefined);
      } else {
        setAmount('');
        setDate('');
        setNote('');
      }
    },
  });
  const submit = useSubmitOnce(save);

  return (
    <form
